    /**
     * Tests getting all HealthSystems.
     *
     * @return    Collection
     */
    public List<HealthSystem> testGetAll() throws Throwable {
    LOGGER.info( "HealthSystemTest:testGetAll() - Retrieving Collection of HealthSystems:" );

    StringBuilder msg = new StringBuilder( "-- Failed to get all HealthSystem : " );
    List<HealthSystem> collection  = null;

    try {
        // call the static get method on the HealthSystemService
        collection = service.getAllHealthSystem();

        if ( collection == null || collection.size() == 0 ) {
            LOGGER.warning( unexpectedErrorMsg );
            LOGGER.warning( "-- " + msg.toString() + " Empty collection returned."  );
        }
        else {
            // Now print out the values
            HealthSystem currEntity  = null;
            Iterator<HealthSystem> iter = collection.iterator();

            while( iter.hasNext() ) {
                // Retrieve the entity
                currEntity = iter.next();

                assertNotNull( currEntity,"-- null value object in Collection." );
                assertNotNull( currEntity.getHealthSystemId(), "-- value object in Collection has a null primary key" );

                LOGGER.info( " - " + currEntity.toString() );
            }
        }
    }
    catch ( Throwable e ){
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() );

        throw e;
    }

    return( collection );
}

